<template><section class="product-reference-images"><div class="product-guide-answer-head"><h3>Imágenes del producto · Hasta 3</h3><button type="button" :disabled="busy || !(model || productName)" @click="search">{{model?'Buscar imágenes del modelo':'Buscar imágenes por nombre'}}</button></div><p class="product-guide-note">Selecciona una referencia y confirma que corresponde al modelo antes de guardarla. La primera imagen es la principal. Se optimizan a WebP, hasta 1280 px y menos de 1 MB por imagen.</p><div class="reference-slots"><article v-for="(image,i) in images" :key="i"><strong>{{i===0?'Principal':'Imagen '+(i+1)}}</strong><img loading="lazy" v-if="image" :src="'/resources/images/productos/'+image" :alt="'Imagen guardada '+(i+1)"><span v-else class="reference-empty">Sin imagen</span><button type="button" :disabled="busy || !canEdit || !selected || !reviewed || !loaded" @click="save(i)">{{image?'Reemplazar':'Guardar en'}} {{i===0?'principal':'imagen '+(i+1)}}</button></article></div><p v-if="busy" role="status" class="product-guide-loading">{{status}}</p><p v-if="error" role="alert" class="product-guide-error">{{error}}</p><p v-if="success" role="status" class="product-knowledge-success">{{success}}</p><div v-if="candidates.length" class="reference-candidates"><article v-for="candidate in candidates" :key="candidate.url" :class="{selected:selected===candidate.url}"><img :src="candidate.url" :alt="candidate.title" loading="lazy" referrerpolicy="no-referrer" @error="imageFailed($event)"><a :href="candidate.source" target="_blank" rel="noopener noreferrer">{{candidate.title || 'Ver página de origen'}}</a><button type="button" :disabled="busy" @click="choose(candidate.url)">{{selected===candidate.url?'Seleccionada':'Elegir imagen'}}</button></article></div><p v-if="searched && !candidates.length && !busy" class="product-guide-note">No se encontraron imágenes descargables en las fuentes del modelo. Puedes buscar y pegar el enlace directo de una imagen.</p><div class="reference-local"><label>Subir imagen desde mi equipo<input type="file" accept="image/jpeg,image/png,image/webp" :disabled="busy || !canEdit || !loaded" @change="selectLocal"></label><small>Funciona también para servicios sin modelo. JPG, PNG o WebP de hasta 5 MB; se guardan optimizadas.</small></div><div class="reference-manual"><a :href="searchLink" target="_blank" rel="noopener noreferrer">Abrir búsqueda de imágenes por modelo ↗</a><label>Enlace directo de imagen<input v-model="manualUrl" maxlength="2000" placeholder="https://fabricante.com/imagen-del-producto.jpg" :disabled="busy"></label><button type="button" :disabled="busy || !manualUrl.trim()" @click="choose(manualUrl)">Previsualizar enlace</button></div><div v-if="selected" :key="selected" class="reference-selection"><img :src="selected" alt="Vista previa de la imagen seleccionada" referrerpolicy="no-referrer" @error="imageFailed($event)"><label><input type="checkbox" v-model="reviewed" :disabled="busy"> Confirmo que la imagen corresponde al producto y puedo usarla.</label><div class="reference-save-actions"><label>Guardar como<select v-model.number="selectedSlot" :disabled="busy"><option :value="0">Principal</option><option :value="1">Imagen 2</option><option :value="2">Imagen 3</option></select></label><button type="button" class="reference-save-button" :disabled="busy || !canEdit || !reviewed || !loaded" @click="save(selectedSlot)">{{busy?'Guardando…':'Guardar imagen en el producto'}}</button></div><small v-if="images[selectedSlot]">Este espacio ya tiene una imagen. Se reemplazará únicamente esa imagen.</small><small v-if="!reviewed">Marca la confirmación para habilitar el botón Guardar.</small></div></section></template>
<script>
import {guideUrl} from '@/utils/productGuide';
export default {props:['productId','productName','model','csrf','canEdit','initialReference'],data(){return {images:['','',''],candidates:[],selected:'',localData:'',selectedSlot:0,manualUrl:'',reviewed:false,searched:false,busy:false,loaded:false,error:'',success:'',status:'',version:0}},computed:{searchLink(){return 'https://www.google.com/search?tbm=isch&q='+encodeURIComponent([this.productName,this.model,'producto'].filter(Boolean).join(' '))}},mounted(){this.load()},watch:{productId(){this.load()}},beforeDestroy(){this.version++;if(this.controller)this.controller.abort()},methods:{async selectLocal(event){const file=event.target.files[0];event.target.value='';if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5242880){this.error='Usa una imagen JPG, PNG o WebP de hasta 5 MB.';return;}const version=this.version;const preview=await new Promise((resolve,reject)=>{const reader=new FileReader;reader.onload=()=>resolve(String(reader.result));reader.onerror=()=>reject(Error('No se pudo leer la imagen.'));reader.readAsDataURL(file)}).catch(e=>{this.error=e.message;return ''});if(version!==this.version||!preview)return;this.selected=preview;this.localData=preview.split(',')[1];this.selectedSlot=Math.max(0,this.images.findIndex(image=>!image));this.reviewed=false;this.error='';this.success=''},async call(body,timeout=30000){if(this.controller)this.controller.abort();this.controller=new AbortController;const timer=setTimeout(()=>this.controller.abort(),timeout);try{const response=await fetch('/api/index.php/ali/producto',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-Ali-CSRF':this.csrf||''},body:JSON.stringify(Object.assign({id:this.productId},body)),signal:this.controller.signal});const data=await response.json();if(!response.ok)throw Error(data.error||'No se pudo completar la operación.');return data}finally{clearTimeout(timer)}},async load(){const version=++this.version;this.images=['','',''];this.candidates=[];this.selected='';this.localData='';this.reviewed=false;this.searched=false;this.error='';this.success='';this.loaded=false;this.busy=true;this.status='Cargando imágenes del producto…';try{const data=await this.call({mode:'image_gallery'});if(version===this.version){this.images=data.imagenes;this.loaded=true;if(this.initialReference)this.choose(this.initialReference)}}catch(e){if(version===this.version)this.error='No se pudo cargar la galería. Vuelve a abrir el asesor antes de guardar imágenes.'}finally{if(version===this.version)this.busy=false}},choose(url){const safe=guideUrl(url.trim());if(!safe){this.error='Usa un enlace directo HTTP o HTTPS de una imagen.';return;}this.localData='';this.selected=safe;const free=this.images.findIndex(image=>!image);this.selectedSlot=free===-1?0:free;this.reviewed=false;this.error='';this.success=''},imageFailed(event){event.target.style.visibility='hidden';event.target.parentElement.classList.add('reference-image-unavailable')},async search(){if(this.busy)return;const version=this.version;this.busy=true;this.status='Buscando imágenes en las fuentes del modelo…';this.error='';this.success='';this.candidates=[];try{const data=await this.call({mode:'image_search',exact_model:this.model||this.productName},120000);if(version===this.version){this.candidates=(data.candidates||[]).filter(c=>guideUrl(c.url)&&guideUrl(c.source));this.searched=true}}catch(e){if(version===this.version)this.error=e.name==='AbortError'?'La búsqueda tardó demasiado. Puedes usar un enlace directo o volver a buscar.':e.message}finally{if(version===this.version)this.busy=false}},async save(index){if(this.busy||!this.reviewed||!this.canEdit||!this.loaded)return;const version=this.version;this.busy=true;this.status='Guardando la imagen elegida en el producto…';this.error='';this.success='';try{const data=await this.call({mode:this.localData?'image_upload':'image_import',slot:index+1,...(this.localData?{data:this.localData}:{url:this.selected}),expected:this.images[index]||'',reviewed:true},55000);if(version!==this.version)return;this.images=data.imagenes;this.success='Imagen guardada en '+(index===0?'Principal':'Imagen '+(index+1))+'. Ya está disponible en el producto.';this.$root.$emit('product:images-updated',{id:this.productId,images:this.images});this.selected='';this.reviewed=false}catch(e){if(version===this.version)this.error=e.name==='AbortError'?'No se recibió confirmación. Vuelve a abrir la galería para comprobar si se guardó.':e.message}finally{if(version===this.version)this.busy=false}}}}
</script>
<style>
.product-reference-images{background:white;border:1px solid #d6e1f2;border-radius:14px;margin:18px 0;padding:18px}.product-reference-images h3{margin:0!important}.reference-slots,.reference-candidates{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:15px 0}.reference-slots article,.reference-candidates article{display:flex;flex-direction:column;gap:9px;min-width:0;padding:12px;border:1px solid #d6e1ef;border-radius:12px;background:#fbfcff}.reference-slots img,.reference-empty,.reference-candidates img{width:100%;height:125px;object-fit:contain;border-radius:8px;background:#f1f5fa}.reference-empty{display:flex;align-items:center;justify-content:center;color:#7488a2}.reference-candidates article.selected{border:2px solid #6955c4;background:#f2efff}.reference-candidates a{font-size:13px;line-height:1.4}.reference-slots button,.reference-candidates button{font-size:13px!important;padding:9px!important;margin-top:auto}.reference-manual{border-top:1px solid #dee6f2;padding-top:14px}.reference-manual label{display:block;margin:12px 0;font-size:14px}.reference-manual input{display:block;width:100%;padding:12px;border:1px solid #c8d6eb;border-radius:9px;margin-top:6px;font-size:15px}.reference-selection{margin-top:15px;padding:15px;background:#f1f6ff;border:1px solid #ceddf5;border-radius:12px}.reference-selection>img{display:block;width:100%;height:160px;object-fit:contain;margin-bottom:12px}.reference-selection label{display:flex;gap:9px;align-items:flex-start;font-size:14px}.reference-selection input{margin-top:6px}.reference-image-unavailable:before{content:'Vista previa no disponible';font-size:12px;color:#7a8295}@media(max-width:600px){.product-reference-images{padding:13px}.reference-slots,.reference-candidates{gap:6px}.reference-slots article,.reference-candidates article{padding:7px}.reference-slots img,.reference-empty,.reference-candidates img{height:85px}.reference-slots button{font-size:11px!important}}
.reference-save-actions{display:flex;align-items:flex-end;gap:12px;margin:16px 0 10px;flex-wrap:wrap}.reference-save-actions label{display:flex;flex-direction:column;gap:6px;min-width:150px;font-weight:650;margin:0}.reference-save-actions select{width:100%;max-width:none;padding:11px;border:1px solid #b9c9e5;border-radius:9px;background:white}.product-guide .reference-save-button{background:#167d69;color:white;border-color:#167d69;min-height:46px;padding:12px 20px;font-size:16px;flex:1}.product-guide .reference-save-button:hover:not(:disabled){background:#126552}.reference-save-button:disabled{opacity:.55}@media(max-width:600px){.reference-save-actions{align-items:stretch;flex-direction:column}.reference-save-actions label,.reference-save-button{width:100%}}
.reference-local{margin:16px 0;padding:14px;background:#eef6f5;border:1px solid #c7e1dc;border-radius:10px}.reference-local label{display:block;font-weight:600}.reference-local input{display:block;margin:10px 0;width:100%;font-size:14px}
</style>
